import styled from '@emotion/styled';
import { theme } from 'theme';

interface StyledFirstColumnCellRendererImageProps {
  $isBeyondBeer?: boolean;
  $isConfigImage?: boolean;
}

const StyledFirstColumnCellRendererImage = styled.img<StyledFirstColumnCellRendererImageProps>(
  ({ $isBeyondBeer, $isConfigImage }) => ({
    objectFit: 'contain',
    mixBlendMode: 'multiply',
    ...($isBeyondBeer && {
      width: '24px !important',
      height: '24px !important',
    }),
    ...($isConfigImage === true && {
      width: '34px',
      height: '34px',
      borderRadius: '50%',
      backgroundColor: '#fff',
      border: '1px solid rgba(0, 0, 0, 0.08)',
    }),
    ...($isConfigImage === false && {
      width: 'auto',
      height: '80%',
      borderRadius: '0%',
    }),
  }),
);

const StyledSubtitle = styled.span({
  fontSize: '16px',
  fontWeight: '400',
  fontFamily: theme.fonts.heading,
  color: '#67665F',
  marginLeft: '4px',
});

export { StyledFirstColumnCellRendererImage, StyledSubtitle };
